ToNanoseconds.example:
#include <cinux/time.hpp>

using namespace cinux::base::time;

void Example() {
    constexpr auto kHalf = ToNanoseconds(500_ms);  // kHalf.value = 500000000 · 半秒
    static_assert(kHalf.value == 500000000ULL);
    static_assert(ToNanoseconds(2_s).value == 2000000000ULL);   // 2 秒
    static_assert(ToNanoseconds(1500_us).value == 1500000ULL);  // 1500 微秒
}

UnixSecondsOf.example:
#include <cinux/time.hpp>

using namespace cinux::base::time;

void Example() {
    constexpr CivilTime kEpoch{
        .year = 1970, .month = 1, .day = 1, .hour = 0, .minute = 0, .second = 0};
    static_assert(UnixSecondsOf(kEpoch) == 0ULL);  // 0 · 纪元起点

    constexpr CivilTime kNoon{
        .year = 2026, .month = 11, .day = 9, .hour = 12, .minute = 0, .second = 0};
    // 1794225600 · 2026-11-09T12:00:00Z 距纪元的秒数
    static_assert(UnixSecondsOf(kNoon) == 1794225600ULL);
}
